run_wizard() {

# ── NOSION · Phase 4 ขั้น 7 — worker + Redis บน Fly.io และค่าที่ API (Vercel) ต้องใช้คู่กัน ──
# รันจากรากของ repo: bash scripts/fly-staging-setup.sh
# ค่าที่กรอก/สร้างถูกจำไว้ใน .env.staging.fly (gitignore แล้ว · mode 0600) — รันซ้ำได้ กด Enter ใช้ค่าเดิม
ENV_FILE=".env.staging.fly"
TOTAL_STAGES=10
WORKER_APP="nosion-staging-worker"
REDIS_APP="nosion-staging-redis"
REGION="sin"
STAGING_WEB="https://nosion-staging-web.vercel.app"

[[ -f ops/fly/worker.fly.toml ]] || { warn "รันจากรากของ repo NOSION: bash scripts/fly-staging-setup.sh"; exit 1; }

# คัดลอกลง clipboard (macOS / Linux / WSL) — ค่าลับไม่ต้องโผล่บนจอ
copy() {
  if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  else return 1; fi
}
app_exists() { flyctl status -a "$1" >/dev/null 2>&1; }

banner "NOSION staging · worker + Redis บน Fly.io"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "ติดตั้งและล็อกอิน flyctl"
if ! command -v flyctl >/dev/null 2>&1; then
  say "ยังไม่มี flyctl ในเครื่อง"
  if command -v brew >/dev/null 2>&1 && confirm "ติดตั้งด้วย Homebrew (brew install flyctl) เลยไหม"; then
    brew install flyctl
  else
    open_url "https://fly.io/docs/flyctl/install/"
    step "ติดตั้งตามหน้านั้น แล้วเปิด terminal ใหม่ให้มีคำสั่ง flyctl"
    pause "ติดตั้งเสร็จแล้วกด Enter"
  fi
fi
command -v flyctl >/dev/null 2>&1 || { warn "ยังหา flyctl ไม่เจอ — ติดตั้งแล้วรันใหม่"; exit 1; }
if ! flyctl auth whoami >/dev/null 2>&1; then
  step "จะเปิดเบราว์เซอร์ให้ล็อกอิน Fly.io (สมัครใหม่ได้ — ต้องใส่บัตรเพื่อยืนยันตัว ใช้น้อยแทบไม่เสียเงิน)"
  flyctl auth login
fi
say "ล็อกอินเป็น: $(flyctl auth whoami)"
pause "ถูกบัญชีแล้วกด Enter"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "สร้างแอป $WORKER_APP + $REDIS_APP และ volume ของ Redis"
say "สองแอปในบัญชี Fly ของคุณ · region $REGION (สิงคโปร์ ใกล้ Supabase)"
say "Redis ไม่มีพอร์ตสาธารณะ — worker คุยผ่านเครือข่ายภายใน $REDIS_APP.internal"
if confirm "สร้างแอปและ volume 1 GB เลยไหม (ข้ามอันที่มีอยู่แล้ว)"; then
  app_exists "$REDIS_APP"  || flyctl apps create "$REDIS_APP"
  app_exists "$WORKER_APP" || flyctl apps create "$WORKER_APP"
  if flyctl volumes list -a "$REDIS_APP" 2>/dev/null | grep -q redis_data; then
    note "มี volume redis_data อยู่แล้ว"
  else
    flyctl volumes create redis_data --size 1 --region "$REGION" -a "$REDIS_APP" --yes
  fi
  printf '  %s✓%s พร้อมแล้ว\n' "$GREEN" "$RESET"
else
  warn "ข้าม — ขั้นถัดไปต้องมีทั้งสองแอป"
fi
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Redis: รหัสผ่าน + deploy"
REDIS_PASSWORD=$(_existing REDIS_PASSWORD || true)
if [[ -z "$REDIS_PASSWORD" ]]; then
  REDIS_PASSWORD=$(openssl rand -hex 24)
  note "สุ่มรหัสผ่าน Redis ใหม่ให้แล้ว"
fi
write_env REDIS_PASSWORD "$REDIS_PASSWORD"
printf 'REDIS_PASSWORD=%s\n' "$REDIS_PASSWORD" | flyctl secrets import -a "$REDIS_APP" --stage >/dev/null
printf '  %s✓ set%s Fly secret REDIS_PASSWORD (%s)\n' "$GREEN" "$RESET" "$REDIS_APP"
if confirm "deploy Redis ขึ้น Fly ตอนนี้ไหม (build บนเครื่องของ Fly ~1 นาที)"; then
  flyctl deploy . --config ops/fly/redis.fly.toml --dockerfile ops/fly/redis.Dockerfile --remote-only --ha=false
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "กุญแจ Web Push (VAPID) + secret ของปุ่มใน notification"
say "สร้างใหม่ครั้งเดียวแล้วใช้ตลอด — เปลี่ยนภายหลัง = ทุกเครื่องต้องกดเปิดการแจ้งเตือนใหม่"
VAPID_PUBLIC_KEY=$(_existing VAPID_PUBLIC_KEY || true)
VAPID_PRIVATE_KEY=$(_existing VAPID_PRIVATE_KEY || true)
if [[ -z "$VAPID_PUBLIC_KEY" || -z "$VAPID_PRIVATE_KEY" ]]; then
  pair=$(node -e "
    const e = require('crypto').createECDH('prime256v1'); e.generateKeys();
    const p = e.getPrivateKey(); const pad = Buffer.concat([Buffer.alloc(32 - p.length), p]);
    console.log(e.getPublicKey().toString('base64url') + ' ' + pad.toString('base64url'));")
  VAPID_PUBLIC_KEY=${pair% *}; VAPID_PRIVATE_KEY=${pair#* }
  note "สร้างคู่กุญแจ VAPID ใหม่แล้ว (ECDSA P-256)"
fi
write_env VAPID_PUBLIC_KEY "$VAPID_PUBLIC_KEY"
write_env VAPID_PRIVATE_KEY "$VAPID_PRIVATE_KEY"
# push service (โดยเฉพาะ Apple) ปฏิเสธ push ที่ subject ไม่ใช่อีเมล/URL จริง — ถามซ้ำจนได้อีเมลที่มี @
while :; do
  ask VAPID_SUBJECT "อีเมลติดต่อสำหรับ push service (Google/Apple ใช้ติดต่อเมื่อมีปัญหา):" || true
  VAPID_SUBJECT="mailto:${VAPID_SUBJECT#mailto:}"
  [[ "$VAPID_SUBJECT" =~ ^mailto:[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$ ]] && break
  warn "ต้องเป็นอีเมลจริง เช่น you@example.com"
done
write_env VAPID_SUBJECT "$VAPID_SUBJECT"
NOTIFICATION_ACTION_SECRET=$(_existing NOTIFICATION_ACTION_SECRET || true)
[[ -n "$NOTIFICATION_ACTION_SECRET" ]] || NOTIFICATION_ACTION_SECRET=$(openssl rand -hex 32)
write_env NOTIFICATION_ACTION_SECRET "$NOTIFICATION_ACTION_SECRET"
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "ฐานข้อมูล: Supabase Session pooler"
say "ค่าเดียวกับ GitHub secret STAGING_DIRECT_URL (ที่ใช้ migrate)"
note "worker รันค้างตลอด จึงใช้ Session pooler พอร์ต 5432 — ไม่ใช่ Transaction pooler 6543 ที่ Vercel ใช้"
open_url "https://supabase.com/dashboard/projects"
step "เปิดโปรเจกต์ staging → ปุ่ม Connect (ด้านบน) → แท็บ ORMs หรือ Connection string"
step "เลือก Session pooler · คัดลอก URI ที่ขึ้นต้น postgresql:// และลงท้าย :5432/postgres"
step "แทน [YOUR-PASSWORD] ด้วยรหัสผ่านฐานข้อมูลก่อนวาง"
ask_secret DATABASE_URL "วาง DATABASE_URL (ซ่อนอยู่):"
[[ "$DATABASE_URL" == postgresql://*:5432/* || "$DATABASE_URL" == postgres://*:5432/* ]] \
  || warn "ไม่ได้ลงท้ายด้วยพอร์ต 5432 — ตรวจว่าเป็น Session pooler"
write_env DATABASE_URL "$DATABASE_URL"
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "อีเมล: log หรือ Resend"
say "log = worker บันทึกลง log ไม่ส่งจริง (เริ่มด้วยอันนี้ได้ — push ใช้ได้ปกติ)"
say "resend = ส่งจริง ต้องมีบัญชี Resend และโดเมนที่ยืนยันแล้ว"
MAIL_DRIVER=$(_existing MAIL_DRIVER || echo log)
if confirm "ใช้ Resend ส่งอีเมลจริงไหม (ตอบ N = log)"; then
  MAIL_DRIVER=resend
  open_url "https://resend.com/api-keys"
  step "Create API Key → สิทธิ์ Sending access → คัดลอก (ขึ้นต้น re_)"
  ask_secret RESEND_API_KEY "วาง RESEND_API_KEY:"
  write_env RESEND_API_KEY "$RESEND_API_KEY"
  step "ผู้ส่งต้องเป็นโดเมนที่ยืนยันแล้วใน Resend → Domains"
  ask EMAIL_FROM "EMAIL_FROM (เช่น NOSION <noreply@yourdomain.com>):"
  write_env EMAIL_FROM "$EMAIL_FROM"
else
  MAIL_DRIVER=log
fi
write_env MAIL_DRIVER "$MAIL_DRIVER"
pause

