stage "ตั้ง secrets ของ worker + deploy"
REDIS_URL="redis://default:${REDIS_PASSWORD}@${REDIS_APP}.internal:6379"
# API อยู่หลัง proxy ของ web (origin เดียวกัน) — ลิงก์เลิกรับอีเมล/ปุ่มใน notification ชี้มาที่นี่
{
  printf 'DATABASE_URL=%s\n' "$DATABASE_URL"
  printf 'REDIS_URL=%s\n' "$REDIS_URL"
  printf 'VAPID_PUBLIC_KEY=%s\n' "$VAPID_PUBLIC_KEY"
