    printf 'EMAIL_FROM=%s\n' "$EMAIL_FROM"
  fi
} | flyctl secrets import -a "$WORKER_APP" --stage >/dev/null
printf '  %s✓ set%s Fly secrets ของ %s (ส่งผ่าน stdin ไม่โผล่ใน process list)\n' "$GREEN" "$RESET" "$WORKER_APP"
if confirm "deploy worker ตอนนี้ไหม (build image บนเครื่องของ Fly ~3–5 นาที)"; then
  flyctl deploy . --config ops/fly/worker.fly.toml --dockerfile docker/worker.Dockerfile --remote-only --ha=false
fi
