# ── 9 ────────────────────────────────────────────────────────────────────
stage "Deploy token → GitHub (deploy worker อัตโนมัติหลัง CI เขียว)"
say "token จำกัดสิทธิ์แค่ deploy แอป $WORKER_APP — GitHub เก็บใน environment staging"
FLY_API_TOKEN=$(flyctl tokens create deploy -a "$WORKER_APP" -x 8760h 2>/dev/null | tail -n1)
if [[ -n "$FLY_API_TOKEN" ]] && command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 \
