  WRITTEN_SECRET+=("FLY_API_TOKEN (env staging)")
  printf '  %s✓ set%s GitHub secret FLY_API_TOKEN (environment staging)\n' "$GREEN" "$RESET"
else
  SKIPPED+=("GitHub secret FLY_API_TOKEN ใน environment staging: flyctl tokens create deploy -a $WORKER_APP | gh secret set FLY_API_TOKEN --env staging")
  warn "ตั้ง FLY_API_TOKEN ไม่สำเร็จ — ทำเองตามสรุปท้าย wizard"
fi
pause

# ── 10 ───────────────────────────────────────────────────────────────────
stage "ตรวจ: worker พร้อม + redeploy staging"
flyctl checks list -a "$WORKER_APP" || true
note "ควรเห็น ready = passing"
flyctl logs -a "$WORKER_APP" --no-tail 2>/dev/null | grep -E "พร้อมรับงานแล้ว|VAPID|ล้มเหลว|error" | tail -n 5 || true
note "ควรเห็น 'NOSION worker พร้อมรับงานแล้ว' และไม่มีคำเตือนเรื่อง VAPID"
if command -v gh >/dev/null 2>&1 && confirm "สั่ง Deploy staging ตอนนี้ไหม (API จะอ่าน env ใหม่จาก Vercel)"; then
  gh workflow run "Deploy staging" && note "ดูความคืบหน้า: gh run watch"
fi
say "เสร็จแล้วตรวจ: เปิด $STAGING_WEB/settings บนมือถือ → เปิดการแจ้งเตือน → ตั้งบิลเตือนล่วงหน้า"
pause "กด Enter เพื่อดูสรุป"

finish
}

run_wizard "$@"; exit
